{"metadata":{"kernelspec":{"language":"python","display_name":"Python 3","name":"python3"},"language_info":{"name":"python","version":"3.12.13","mimetype":"text/x-python","codemirror_mode":{"name":"ipython","version":3},"pygments_lexer":"ipython3","nbconvert_exporter":"python","file_extension":".py"},"kaggle":{"accelerator":"none","dataSources":[{"sourceType":"datasetVersion","sourceId":19096563}],"isInternetEnabled":true,"language":"python","sourceType":"script","isGpuEnabled":false}},"nbformat_minor":4,"nbformat":4,"cells":[{"cell_type":"code","source":"\"\"\"\nClauseLens — Node 2\nStructured chunk preparation.\n\nThis module converts Node 1's output into the canonical\nchunk representation consumed by the Node 2 indexer.\n\"\"\"\n\nfrom typing import Any\n\n\nREQUIRED_CHUNK_FIELDS = {\n    \"chunk_id\",\n    \"text\",\n    \"page_start\",\n    \"page_end\",\n    \"heading_path\",\n}\n\n\ndef prepare_chunks(\n    documents: dict[str, dict[str, Any]],\n    version_ids: dict[str, str] | None = None,\n) -> list[dict[str, Any]]:\n    \"\"\"\n    Convert Node 1 document output into Node 2 structured chunks.\n\n    Parameters\n    ----------\n    documents:\n        Output produced by Node 1's process_documents().\n\n    version_ids:\n        Optional mapping from document_id to version_id.\n\n    Returns\n    -------\n    list[dict[str, Any]]\n        Canonical Node 2 chunk records.\n    \"\"\"\n\n    if version_ids is None:\n        version_ids = {}\n\n    all_chunks = []\n\n    for document_name, document in documents.items():\n\n        document_id = document.get(\n            \"document_id\",\n            document_name,\n        )\n\n        chunks = document.get(\n            \"chunks\",\n            [],\n        )\n\n        if not isinstance(chunks, list):\n            raise TypeError(\n                f\"Chunks for '{document_id}' must be a list.\"\n            )\n\n        version_id = version_ids.get(\n            document_id\n        )\n\n        for chunk in chunks:\n\n            missing_fields = (\n                REQUIRED_CHUNK_FIELDS\n                - chunk.keys()\n            )\n\n            if missing_fields:\n                raise ValueError(\n                    f\"Chunk is missing required fields: \"\n                    f\"{sorted(missing_fields)}\"\n                )\n\n            text = chunk[\"text\"]\n\n            if not isinstance(text, str):\n                raise TypeError(\n                    f\"Chunk '{chunk['chunk_id']}' \"\n                    f\"text must be a string.\"\n                )\n\n            if not text.strip():\n                raise ValueError(\n                    f\"Chunk '{chunk['chunk_id']}' \"\n                    f\"contains empty text.\"\n                )\n\n            structured_chunk = {\n                \"chunk_id\": chunk[\"chunk_id\"],\n                \"document_id\": document_id,\n                \"version_id\": version_id,\n                \"text\": text,\n                \"page_start\": chunk[\"page_start\"],\n                \"page_end\": chunk[\"page_end\"],\n                \"heading_path\": chunk[\"heading_path\"],\n            }\n\n            all_chunks.append(\n                structured_chunk\n            )\n\n    _validate_chunk_ids(all_chunks)\n\n    return all_chunks\n\n\ndef _validate_chunk_ids(\n    chunks: list[dict[str, Any]],\n) -> None:\n    \"\"\"\n    Ensure every chunk ID is unique.\n    \"\"\"\n\n    chunk_ids = [\n        chunk[\"chunk_id\"]\n        for chunk in chunks\n    ]\n\n    if len(chunk_ids) != len(set(chunk_ids)):\n        raise ValueError(\n            \"Duplicate chunk IDs detected.\"\n        )","metadata":{"_uuid":"50c276b9-bf13-445c-81e0-2afe41aaba50","_cell_guid":"5fa06299-d9d4-4714-84e2-167755ff79ca","trusted":true,"collapsed":false,"jupyter":{"outputs_hidden":false},"execution":{"iopub.status.busy":"2026-08-26T14:35:33.205129Z","iopub.execute_input":"2026-08-26T14:35:33.205368Z","iopub.status.idle":"2026-08-26T14:35:33.216858Z","shell.execute_reply.started":"2026-08-26T14:35:33.205347Z","shell.execute_reply":"2026-08-26T14:35:33.215842Z"}},"outputs":[],"execution_count":1}]}